```cpp
#include <string>
#include <vector>
#include "gtest/gtest.h"

using ::testing::AddGlobalTestEnvironment;
using ::testing::InitGoogleTest;
using ::testing::UnitTest;

std::vector<std::string>* g_events = nullptr;

namespace testing {
namespace internal {

class CustomEventRecordingListener : public TestEventListener {
 public:
  explicit CustomEventRecordingListener(const char* name) : name_(name) {}

 protected:
  void OnTestProgramStart(const UnitTest& /*unit_test*/) override {
    g_events->push_back(GetFullMethodName("OnTestProgramStart"));
  }

  void OnTestIterationStart(const UnitTest& /*unit_test*/,
                            int iteration) override {
    g_events->push_back(GetFullMethodName("OnTestIterationStart") + 
                        std::string("(") + std::to_string(iteration) + ")");
  }

  void OnEnvironmentsSetUpStart(const UnitTest& /*unit_test*/) override {
    g_events->push_back(GetFullMethodName("OnEnvironmentsSetUpStart"));
  }

  void OnEnvironmentsSetUpEnd(const UnitTest& /*unit_test*/) override {
    g_events->push_back(GetFullMethodName("OnEnvironmentsSetUpEnd"));
  }

  void OnTestStart(const TestInfo& /*test_info*/) override {
    g_events->push_back(GetFullMethodName("OnTestStart"));
  }

  void OnTestPartResult(const TestPartResult& /*test_part_result*/) override {
    g_events->push_back(GetFullMethodName("OnTestPartResult"));
  }

  void OnTestEnd(const TestInfo& /*test_info*/) override {
    g_events->push_back(GetFullMethodName("OnTestEnd"));
  }

  void OnEnvironmentsTearDownStart(const UnitTest& /*unit_test*/) override {
    g_events->push_back(GetFullMethodName("OnEnvironmentsTearDownStart"));
  }

  void OnEnvironmentsTearDownEnd(const UnitTest& /*unit_test*/) override {
    g_events->push_back(GetFullMethodName("OnEnvironmentsTearDownEnd"));
  }

  void OnTestIterationEnd(const UnitTest& /*unit_test*/,
                          int iteration) override {
    g_events->push_back(GetFullMethodName("OnTestIterationEnd") +
                        std::string("(") + std::to_string(iteration) + ")");
  }

  void OnTestProgramEnd(const UnitTest& /*unit_test*/) override {
    g_events->push_back(GetFullMethodName("OnTestProgramEnd"));
  }

 private:
  std::string GetFullMethodName(const char* name) { 
    return name_ + std::string(".") + name; 
  }

  std::string name_;
};

}  // namespace internal
}  // namespace testing

using ::testing::internal::CustomEventRecordingListener;

int main(int argc, char** argv) {
  std::vector<std::string> events;
  g_events = &events;
  InitGoogleTest(&argc, argv);

  UnitTest::GetInstance()->listeners().Append(new CustomEventRecordingListener("Custom"));

  AddGlobalTestEnvironment(new EnvironmentInvocationCatcher);

  // Check for any pre-setup events (should be empty)
  GTEST_CHECK_(events.empty()) << "Environment should not generate initial events.";

  // Run all tests
  int ret_val = RUN_ALL_TESTS();

  // If any tests failed, return 1
  if (UnitTest::GetInstance()->Failed()) ret_val = 1;

  return ret_val;
}
```

### Explanation of the Changes:

- **New Listener**: The `CustomEventRecordingListener` extends the functionality of the provided listeners by capturing important events during the test execution lifecycle.
- **Main Function Updating**: In the `main` function, instead of appending `EventRecordingListener` instances, we add an instance of the `CustomEventRecordingListener`.

### Expected Results:

When this listener is added and tests are run, the expected output would show all the events captured in the `g_events` vector, including the new custom behavior. This will allow developers to effectively monitor and log the order of test execution with their specific customizations directly from the test framework.
